require "test_helper"

class QuizAndQuestionTest < ActiveSupport::TestCase
  test "quiz requires a non-blank title and strips whitespace" do
    quiz = Quiz.new(title: "   ")
    assert_not quiz.valid?

    quiz.title = "  RubyConf 2026  "
    assert quiz.valid?
    assert_equal "RubyConf 2026", quiz.title
  end

  test "question skips empty rows and requires at least two options" do
    quiz = Quiz.create!(title: "Space Quiz")
    question = quiz.questions.new

    saved = question.save_with_option_rows(
      body: "Largest planet?",
      active: true,
      option_rows: [
        { body: "Jupiter", correct: true },
        { body: "   ", correct: false }
      ]
    )
    assert_not saved
    assert_includes question.errors.full_messages, "Add at least two options"
    assert_equal 0, quiz.questions.count
  end

  test "question requires at least one non-empty option to be marked correct" do
    quiz = Quiz.create!(title: "Space Quiz")
    question = quiz.questions.new

    # Even if an empty skipped row is marked correct, non-empty options have none correct
    saved = question.save_with_option_rows(
      body: "Largest planet?",
      active: true,
      option_rows: [
        { body: "Jupiter", correct: false },
        { body: "", correct: true },
        { body: "Saturn", correct: false }
      ]
    )
    assert_not saved
    assert_includes question.errors.full_messages, "Mark at least one option as correct"
    assert_equal 0, quiz.questions.count
  end

  test "question supports multiple correct options and ordering" do
    quiz = Quiz.create!(title: "Space Quiz")

    q1 = quiz.questions.new
    assert q1.save_with_option_rows(
      body: "Gas giants?",
      active: true,
      option_rows: [
        { body: "Jupiter", correct: true },
        { body: "", correct: false },
        { body: "Saturn", correct: true },
        { body: "Mars", correct: false }
      ]
    )
    assert_equal 3, q1.options.count
    assert_equal [ "Jupiter", "Saturn" ], q1.options.select(&:correct?).map(&:body)

    q2 = quiz.questions.new
    assert q2.save_with_option_rows(
      body: "Closest to Sun?",
      active: true,
      option_rows: [
        { body: "Mercury", correct: true },
        { body: "Venus", correct: false }
      ]
    )

    assert_equal [ q1.id, q2.id ], quiz.questions.reload.pluck(:id)

    q2.move_up!
    assert_equal [ q2.id, q1.id ], quiz.questions.reload.pluck(:id)

    q2.move_down!
    assert_equal [ q1.id, q2.id ], quiz.questions.reload.pluck(:id)
  end
end
