  end

  test "GET /up responds 200 without auth and accepts any host" do
    get "/up", headers: { "Host" => "projector.hall-a.internal:8080" }
    assert_response :success
  end

  test "every moderator route requires valid HTTP Basic credentials" do
    quiz = Quiz.create!(title: "Test Quiz")
    question = quiz.questions.new
    question.save_with_option_rows(
      body: "Q1?",
      active: true,
      option_rows: [ { body: "A", correct: true }, { body: "B", correct: false } ]
