    protected_paths = [
      "/moderate",
      "/moderate/quizzes/new",
      "/moderate/quizzes/#{quiz.id}",
      "/moderate/quizzes/#{quiz.id}/settings",
      "/moderate/quizzes/#{quiz.id}/questions/new",
      "/moderate/quizzes/#{quiz.id}/questions/#{question.id}/edit",
      "/moderate/quizzes/#{quiz.id}/preview"
    ]

    protected_paths.each do |path|
      get path
      assert_response :unauthorized, "Expected 401 without credentials for #{path}"

      bad_auth = {
        "HTTP_AUTHORIZATION" => ActionController::HttpAuthentication::Basic.encode_credentials("confmod", "wrong")
      }
      get path, headers: bad_auth
      assert_response :unauthorized, "Expected 401 with wrong password for #{path}"

      bad_user = {
        "HTTP_AUTHORIZATION" => ActionController::HttpAuthentication::Basic.encode_credentials("wrong", "s3cr3t!")
      }
      get path, headers: bad_user
      assert_response :unauthorized, "Expected 401 with wrong username for #{path}"

      get path, headers: @auth_header.merge("Host" => "any-host.example.org")
      assert_response :success, "Expected 200 with valid credentials for #{path}"
    end
  end
end
