export default class extends Controller {
  static targets = ["summary", "item"]

  toggle(event) {
    const checkbox = event.currentTarget
    const form = checkbox.form
    const item = checkbox.closest(".question-item")

    if (item) {
      item.classList.toggle("question-item--inactive", !checkbox.checked)
    }
    this.refreshCounts()

    if (form) {
      const csrfToken = document.querySelector('meta[name="csrf-token"]')?.content || ""
      fetch(form.action, {
        method: "POST",
        body: new FormData(form),
        credentials: "same-origin",
        keepalive: true,
        headers: {
          "X-Requested-With": "XMLHttpRequest",
          "X-CSRF-Token": csrfToken
        }
      })
    }
  }

  refreshCounts() {
    let activeCount = 0
    const totalCount = this.itemTargets.length

    this.itemTargets.forEach((item) => {
      const checkbox = item.querySelector('input[type="checkbox"]')
      const numEl = item.querySelector(".question-item__num")
      const isActive = checkbox ? checkbox.checked : !item.classList.contains("question-item--inactive")

      if (isActive) {
        activeCount += 1
        if (numEl) numEl.textContent = String(activeCount)
      } else {
        if (numEl) numEl.textContent = "—"
      }
    })

    if (this.hasSummaryTarget) {
      const noun = totalCount === 1 ? "question" : "questions"
      this.summaryTarget.textContent = `${activeCount} of ${totalCount} ${noun} active`
    }
